import{_ as p,o as a,c as t,a3 as e}from"./chunks/framework.DdpBa4_E.js";const o="/ReadBooks/assets/image-035.DyIZ0bvc.jpg",s="/ReadBooks/assets/image-036.CmHlMoAG.jpg",f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/101-有效沟通的两个阶段.md","filePath":"books/attached/101-有效沟通的两个阶段.md","lastUpdated":1794316978000}'),r={name:"books/attached/101-有效沟通的两个阶段.md"};function c(d,_,i,n,l,m){return a(),t("div",null,[..._[0]||(_[0]=[e('<h3 id="有效沟通的两个阶段" tabindex="-1">有效沟通的两个阶段 <a class="header-anchor" href="#有效沟通的两个阶段" aria-label="Permalink to &quot;有效沟通的两个阶段&quot;">​</a></h3><p>||初始阶段</p><p>当你还对有效沟通不怎么习惯的时候，建立一套你想传递的基础信息模板是非常有效的方法。你最好不要选择情绪不佳的时候做这件事，还有很重要的一点，就是你的朋友可能会给你一些曲线救国的建议，以此来满足情感需求，比如故意让伴侣妒忌，你必须得抛却这些建议。如果条件允许，你应该找到自己的安全角色榜样（详见第9章），或是安全型依恋风格的朋友，再或是非常熟悉有效沟通法则的人来帮助你组织这套信息模板。确定下基本的体量以后，试着用最适宜的语调叙述出来。将这些信息先写下来，能够在你退缩或者忘掉“底线”之时，帮助你克服恐惧和焦虑，同时也有助于带着自信来面对伴侣。当你对有效沟通熟能生巧，并且在实际生活中尝到甜头，有效沟通也就自然成了你的本能之举。</p><p>||实践阶段</p><p>回答下面的问题，定下有效沟通的基调。</p><p>我为什么会在这段关系中感觉到紧张与不安全（依恋机制的激活和抑制）？我的伴侣到底做了什么，才让我有这种感觉（这里可以参见第9章的依恋关系目录）？</p><p>1______________________</p><p>2______________________</p><p>3______________________</p><p>我伴侣做些什么，会令我感觉到安心与爱意？</p><p>1______________________</p><p>2______________________</p><p>3______________________</p><p>哪些行为是我最想体验或者展开讨论的？</p><p>1______________________</p><p>2______________________</p><p>3______________________</p><p>这最后一个问题的答案，就将指导你定下第一次有效沟通的基调。接下来，就将自己的有效沟通模板简短地写在下面，记得附上有效沟通的五条原则。</p><p>我的有效沟通脚本：</p><hr><hr><hr><hr><hr><p>多看一下后面的例子，它们是在特定情况下，有着特定意义的有效沟通方法，注意体会有效沟通与无效沟通的不同之处。你就能明白，为什么伴侣在两种沟通方式之下的反应，有如此显著的差别了。</p><p><img src="'+o+'" alt="" loading="lazy"></p><p><img src="'+s+'" alt="" loading="lazy"></p><p>非常重要的一点在于，即使采用了有效沟通，有些事情也没法马上解决。事情的关键点在于对方的反应，这取决于他是否在意你的情绪，将你的快乐放在心上，并且愿意做点什么让你舒心。</p>',28)])])}const g=p(r,[["render",c]]);export{f as __pageData,g as default};
